package com.pointverse.app;
import android.content.Context;import android.graphics.*;import android.view.*;import java.util.*;import java.util.function.Consumer;
/** Interactive projection of the same domain/topic/point hierarchy across sphere and mind map. */
final class UniverseCanvas extends View{
    private final Paint paint=new Paint(3);private final List<PointStore.Point> points;private final SemanticIndex index;private final Consumer<String> select;private final boolean mind;
    private final ScaleGestureDetector scale;private float zoom=1,yaw=0,pitch=0,panX=0,panY=0,lastX,lastY,startX,startY;private final Map<String,PointF> hits=new HashMap<>();private String focused="";
    UniverseCanvas(Context c,List<PointStore.Point> p,SemanticIndex i,boolean m,Consumer<String> action){super(c);points=p;index=i;mind=m;select=action;setContentDescription(m?"层级脑图，可拖动、双指缩放并打开想法":"语义宇宙，可旋转、双指缩放并打开想法");scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(.4f,Math.min(8,zoom*d.getScaleFactor()));invalidate();return true;}});}
    protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(0xff080617);hits.clear();paint.setColor(0xff40365a);for(int n=0;n<100;n++){float x=(float)((n*97.337%100)*getWidth()/100),y=(float)((n*41.791%100)*getHeight()/100);c.drawCircle(x,y,n%7==0?1.8f:.8f,paint);}if(mind)tree(c);else sphere(c);}
    private void sphere(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.32f*zoom;Map<String,List<PointStore.Point>> groups=new TreeMap<>();for(PointStore.Point p:points){String key=index.value(p,"domain");groups.computeIfAbsent(key.isEmpty()?"尚未归类":key,k->new ArrayList<>()).add(p);}int group=0;for(Map.Entry<String,List<PointStore.Point>> entry:groups.entrySet()){double phi=group*2.399963;double vertical=groups.size()==1?0:1-2.0*group/Math.max(1,groups.size()-1);double radial=Math.sqrt(1-vertical*vertical),x=radial*Math.cos(phi),z=radial*Math.sin(phi),y=vertical;double xx=x*Math.cos(yaw)+z*Math.sin(yaw),zz=-x*Math.sin(yaw)+z*Math.cos(yaw),yy=y*Math.cos(pitch)-zz*Math.sin(pitch);zz=y*Math.sin(pitch)+zz*Math.cos(pitch);float depth=(float)(1+.22*zz),px=cx+(float)xx*r+panX,py=cy+(float)yy*r+panY,planet=(22+Math.min(45,entry.getValue().size()*3))*zoom*depth;int color=Color.HSVToColor(new float[]{(group*71+220)%360,.5f,.85f});paint.setShader(new RadialGradient(px-planet*.3f,py-planet*.3f,planet*1.5f,new int[]{color,0xff17122d},null,Shader.TileMode.CLAMP));c.drawCircle(px,py,planet,paint);paint.setShader(null);paint.setColor(0xffd7d2f0);paint.setTextSize(12*getResources().getDisplayMetrics().scaledDensity);c.drawText(entry.getKey(),px-planet,py-planet-10,paint);int n=0;for(PointStore.Point p:entry.getValue()){double angle=n++*2.399963;float spread=planet*.72f,tx=px+(float)Math.cos(angle)*spread*(n/(float)Math.max(1,entry.getValue().size())),ty=py+(float)Math.sin(angle)*spread;paint.setColor(p.id.equals(focused)?0xffffd971:0xfff7f4ff);c.drawCircle(tx,ty,p.id.equals(focused)?7:4,paint);hits.put(p.id,new PointF(tx,ty));if(p.id.equals(focused)){paint.setTextSize(13*getResources().getDisplayMetrics().scaledDensity);c.drawText(p.title,tx+12,ty,paint);}}group++;}}
    private void tree(Canvas c){Map<String,Map<String,List<PointStore.Point>>> hierarchy=new TreeMap<>();for(PointStore.Point p:points){String domain=index.value(p,"domain"),topic=index.value(p,"topic");hierarchy.computeIfAbsent(domain.isEmpty()?"尚未归类":domain,k->new TreeMap<>()).computeIfAbsent(topic.isEmpty()?"未分主题":topic,k->new ArrayList<>()).add(p);}float density=getResources().getDisplayMetrics().density,x=24*density+panX,y=32*density+panY;paint.setTextSize(15*density*zoom);paint.setStrokeWidth(1.5f*density);for(Map.Entry<String,Map<String,List<PointStore.Point>>> domain:hierarchy.entrySet()){paint.setColor(0xffa7a0f7);c.drawText(domain.getKey(),x,y,paint);y+=36*density*zoom;for(Map.Entry<String,List<PointStore.Point>> topic:domain.getValue().entrySet()){paint.setColor(0xffc4bedc);c.drawLine(x+8*density,y-16*density,x+24*density,y-16*density,paint);c.drawText(topic.getKey(),x+30*density,y,paint);y+=30*density*zoom;for(PointStore.Point p:topic.getValue()){paint.setColor(p.id.equals(focused)?0xffffd971:Color.WHITE);float px=x+64*density*zoom;String title=p.title.length()>24?p.title.substring(0,24)+"…":p.title;c.drawCircle(px-10*density,y-5*density,3*density,paint);c.drawText(title,px,y,paint);hits.put(p.id,new PointF(px+Math.min(100*density,paint.measureText(title)/2),y-6*density));y+=38*density*zoom;}}y+=18*density*zoom;}}
    public boolean onTouchEvent(MotionEvent e){scale.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=startX=e.getX();lastY=startY=e.getY();}else if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=e.getX()-lastX,dy=e.getY()-lastY;if(!scale.isInProgress()){if(mind){panX+=dx;panY+=dy;}else{yaw+=dx*.007;pitch=Math.max(-1.5f,Math.min(1.5f,pitch+dy*.007f));}}lastX=e.getX();lastY=e.getY();invalidate();}else if(e.getActionMasked()==MotionEvent.ACTION_UP&&Math.hypot(e.getX()-startX,e.getY()-startY)<15){String selected=null;double nearest=50*getResources().getDisplayMetrics().density;for(Map.Entry<String,PointF> hit:hits.entrySet()){double distance=Math.hypot(e.getX()-hit.getValue().x,e.getY()-hit.getValue().y);if(distance<nearest){nearest=distance;selected=hit.getKey();}}if(selected!=null)select.accept(selected);}return true;}
    void reset(){zoom=1;yaw=pitch=panX=panY=0;invalidate();}void focus(String id){focused=id;zoom=Math.max(1.5f,zoom);invalidate();}
}
